"""Decision Models transport wrapper. Native distributions are never recalibrated."""
import argparse
import base64
import io
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

def text(value):
    return value if isinstance(value, str) else json.dumps(value, ensure_ascii=False)

def images(body, maximum=4):
    refs = body.get("images", [])
    if not isinstance(refs, list) or len(refs) > maximum:
        raise ValueError("unsupported image count")
    from PIL import Image
    result = []
    for ref in refs:
        if not isinstance(ref, str) or not ref.startswith(("data:image/png;base64,", "data:image/jpeg;base64,", "data:image/webp;base64,")):
            raise ValueError("images must be PNG/JPEG/WebP base64 data URLs")
        raw = base64.b64decode(ref.split(",", 1)[1], validate=True)
        if len(raw) > 8_000_000:
            raise ValueError("image exceeds 8 MB")
        with Image.open(io.BytesIO(raw)) as image:
            if image.width * image.height > 16_000_000:
                raise ValueError("image exceeds 16 million pixels")
            result.append(image.convert("RGB"))
    return result

def serve(predict, model, port):
    class Handler(BaseHTTPRequestHandler):
        def send(self, status, value):
            data = json.dumps(value, ensure_ascii=False, allow_nan=False).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def do_GET(self):
            if self.path == "/health":
                self.send(200, {"status": "ok", "model": model})
            else:
                self.send(404, {"error": "not found"})
        def do_POST(self):
            if self.path not in ("/v1/systemone", "/v1/multimodal"):
                return self.send(404, {"error": "not found"})
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if not 0 < size <= 48_000_000:
                    return self.send(413, {"error": "request exceeds limit"})
                body = json.loads(self.rfile.read(size))
                if not isinstance(body.get("questions"), dict) or not body["questions"]:
                    raise ValueError("questions must be a nonempty object")
                if self.path == "/v1/multimodal" and not body.get("images"):
                    raise ValueError("multimodal requires images")
                self.send(200, predict(body))
            except (ValueError, KeyError, TypeError) as exc:
                self.send(422, {"error": str(exc)})
            except Exception as exc:
                self.send(500, {"error": type(exc).__name__})
        def log_message(self, *args):
            pass
    # Single worker: native caches and hooks are serialized across requests.
    HTTPServer(("127.0.0.1", port), Handler).serve_forever()

def args():
    p = argparse.ArgumentParser()
    p.add_argument("--weights", required=True)
    p.add_argument("--port", type=int, required=True)
    p.add_argument("--device", default="cuda", choices=["cuda", "cpu", "mps"])
    p.add_argument("--base")
    p.add_argument("--host", default="127.0.0.1", choices=["127.0.0.1"])
    return p.parse_args()

def main():
    a = args()
    if a.device != "cuda":
        raise ValueError("This source-derived Shisa image recipe requires CUDA")
    import torch
    import math
    from transformers import AutoProcessor, Gemma4ForConditionalGeneration
    from readout.vllm_scoring import DIRECT_SYSTEM, LETTERS
    processor = AutoProcessor.from_pretrained(a.weights, local_files_only=True)
    tokenizer = processor.tokenizer
    model = Gemma4ForConditionalGeneration.from_pretrained(
        a.weights, dtype=torch.bfloat16, device_map={"": 0}, local_files_only=True,
        attn_implementation="sdpa").eval()
    def predict(body):
        photos = images(body, maximum=1)
        answers = {}
        input_tokens = 0
        for qid, q in body["questions"].items():
            if q["type"] == "noul":
                options = [("yes", "Yes"), ("no", "No")]
            elif q["type"] == "choice":
                options = [(key, value or key) for key, value in q["criteria"].items()]
            elif q["type"] == "score":
                options = [(str(i), value) for i, value in enumerate(q["criteria"])]
            else:
                raise ValueError("unsupported question type")
            if not 2 <= len(options) <= 26:
                raise ValueError("Shisa requires 2 to 26 option letters")
            letters = list(LETTERS[:len(options)])
            payload = {"evidence": body["state"], "criterion": q["instructions"],
                       "options": [{"letter": letter, "description": desc}
                                   for letter, (_, desc) in zip(letters, options)]}
            content = ([{"type": "image"}] if photos else []) + [{"type": "text", "text": json.dumps(payload, ensure_ascii=False)}]
            messages = [{"role": "system", "content": DIRECT_SYSTEM}, {"role": "user", "content": content}]
            prompt = processor.apply_chat_template(messages, tokenize=False, add_generation_prompt=True, enable_thinking=False)
            prompt_ids = tokenizer.encode(prompt, add_special_tokens=False)
            slots = []
            for letter in letters:
                encoded = tokenizer.encode(letter, add_special_tokens=False)
                if len(encoded) != 1 or tokenizer.decode(encoded) != letter or tokenizer.encode(prompt + letter, add_special_tokens=False) != prompt_ids + encoded:
                    raise ValueError("answer boundary changes tokenization")
                slots.extend(encoded)
            kw = {"images": [photos]} if photos else {}
            inputs = processor(text=[prompt], return_tensors="pt", add_special_tokens=False, **kw)
            ids = inputs["input_ids"]
            input_tokens += int(ids.shape[1])
            bos = tokenizer.bos_token_id
            if ids[0, 0].item() != bos or ids[0, 1].item() == bos:
                raise ValueError("unexpected BOS layout")
            if photos and not int((ids == processor.image_token_id).sum().item()):
                raise ValueError("image tokens missing")
            batch = {key: value.to("cuda", dtype=torch.bfloat16) if value.is_floating_point() else value.to("cuda")
                     for key, value in inputs.items() if hasattr(value, "to")}
            with torch.inference_mode():
                row = model(**batch, logits_to_keep=1, use_cache=False).logits[0, -1].float()
            # BH _tempered_softmax: Python float exp over FP32 selected logits, T=1.
            logits = row[slots].double().cpu().tolist()
            peak = max(logits)
            masses = [math.exp(value - peak) for value in logits]
            probs = [value / sum(masses) for value in masses]
            if q["type"] == "noul":
                answers[qid] = {"type": "noul", "noul": probs[0]}
            elif q["type"] == "choice":
                best = max(range(len(probs)), key=probs.__getitem__)
                answers[qid] = {"type": "choice", "choice": options[best][0],
                                "probabilities": {key: p for (key, _), p in zip(options, probs)}, "confidence": round(probs[best], 6)}
            else:
                answers[qid] = {"type": "score", "score": sum(i*p for i, p in enumerate(probs)),
                                "probabilities": {str(i): p for i, p in enumerate(probs)},
                                "legend": {str(i): text(desc) for i, (_, desc) in enumerate(options)}, "confidence": round(max(probs), 6)}
        return {"model": "shisa-de-1", "answers": answers, "usage": {"input_tokens": input_tokens, "output_tokens": 0}}
    serve(predict, "shisa-de-1", a.port)

if __name__ == "__main__":
    main()
